L5 = lesson('l5', 'mint', '🎁', 'Verbs with indirect objects', 'Động từ đi với 2 tân ngữ: give, show, send…',
 'Cho ai cái gì? Cùng xem cách nói nhé!',
 [when('🧭 Khi nào dùng?', [
    ('🎁', 'Một số động từ đi với **người** rồi đến **vật**: **give, show, send, buy, tell**.', 'Mum gives me a ticket.', 'Mẹ đưa mình một tấm vé.'),
    ('🔁', 'Có hai cách nói: **verb + người + vật** hoặc **verb + vật + to / for + người**.', 'Mum gives a ticket to me.', 'Mẹ đưa tấm vé cho mình.'),
    ('🧭', '**give, show, send, tell** → dùng **to**. **buy, make** → dùng **for**.', 'He buys a gift for her.', 'Anh ấy mua quà cho cô ấy.')]),
  compare('🗂 So sánh 2 cách nói', [
    CI('verb + person + thing', 'sub', 'người rồi vật', '**Người** đứng ngay sau động từ, **không có to / for**.', [('Mum gives me a ticket.', 'Mẹ đưa mình một tấm vé.'), ('He buys her a gift.', 'Anh ấy mua cho cô ấy món quà.')], EM('🎟️')),
    CI('verb + thing + to / for + person', 'aux', 'vật rồi người', 'Đưa **vật** lên trước, thêm **to** hoặc **for** trước người.', [('Mum gives a ticket to me.', 'Mẹ đưa tấm vé cho mình.'), ('He buys a gift for her.', 'Anh ấy mua quà cho cô ấy.')], EM('🎁'))]),
  pattern('1️⃣ Người rồi vật', 'mint', [('subject', 'sub', 'ai'), ('verb', 'v', 'gives, buys'), ('person', 'obj', 'me, him, us'), ('thing', 'pink', 'a ticket')], [
    ('{Mum|sub} {buys|v} {me|obj} {a ticket.|pink}', 'Mẹ mua cho mình một tấm vé.', EM('🎟️')), ('{The actor|sub} {shows|v} {us|obj} {his costume.|pink}', 'Nam diễn viên cho chúng mình xem trang phục.', V('stage')),
    ('{I|sub} {send|v} {him|obj} {a postcard.|pink}', 'Mình gửi cho cậu ấy một tấm bưu thiếp.', EM('✉️'))]),
  pattern('2️⃣ Vật rồi to / for + người', 'rose', [('subject', 'sub', 'ai'), ('verb', 'v', 'gives, buys'), ('thing', 'pink', 'a ticket'), ('to / for', 'aux', 'cho'), ('person', 'obj', 'me, her')], [
    ('{Mum|sub} {gives|v} {a ticket|pink} {to|aux} {me.|obj}', 'Mẹ đưa tấm vé cho mình.', EM('🎟️')), ('{He|sub} {buys|v} {a gift|pink} {for|aux} {her.|obj}', 'Anh ấy mua quà cho cô ấy.', EM('🎁')),
    ('{She|sub} {tells|v} {a story|pink} {to|aux} {us.|obj}', 'Cô ấy kể chuyện cho chúng mình.', EM('📖'))]),
  tip('💡 Mẹo: **give, show, send, tell + to** · **buy, make + for**. Người đứng ngay sau động từ thì **bỏ to / for**.'),
  mistakes([('Mum gives a ticket me.', 'Mum gives me a ticket.', 'Người đứng trước vật.'), ('She sends to him a card.', 'She sends him a card.', 'Người đứng ngay sau động từ thì không dùng to.'),
            ('He buys a present to her.', 'He buys a present for her.', 'buy → for.'), ('She tells a story for me.', 'She tells a story to me.', 'tell → to.')]),
  acts('a5')],
 [Mc('Mum gives ___ a ticket.', 'me', 'I', 'my', 'Sau động từ dùng me (người nhận).', EM('🎟️')),
  Mc('He shows ___ his costume.', 'us', 'we', 'our', 'Sau động từ dùng us (người nhận).'),
  Mc('She sends ___ a postcard.', 'him', 'he', 'his', 'Sau động từ dùng him (người nhận).', EM('✉️')),
  Mc('I buy a present ___ my mum.', 'for', 'to', 'at', 'buy → for.', EM('🎁')),
  Mc('He gives a ticket ___ me.', 'to', 'for', 'at', 'give → to.'),
  Mc('Tell ___ a story, please.', 'me', 'I', 'my', 'Sau động từ dùng me (người nhận).'),
  Mc('She makes a cake ___ us.', 'for', 'to', 'with', 'make → for.'),
  Mc('Show the picture ___ her.', 'to', 'for', 'at', 'show → to.'),
  Mc('Dad buys ___ an ice cream.', 'me', 'I', 'my', 'Sau động từ dùng me (người nhận).'),
  Mc('I send a letter ___ my friend.', 'to', 'for', 'on', 'send → to.', EM('✉️')),
  Fl('Mum gives ___ a ticket.', 'me', ['me', 'I', 'my'], 'Sau động từ dùng me.', EM('🎟️')),
  Fl('He shows ___ the pictures.', 'us', ['us', 'we', 'our'], 'Sau động từ dùng us.'),
  Fl('I send a card ___ her.', 'to', ['to', 'for', 'at'], 'send → to.', EM('✉️')),
  Fl('She buys a gift ___ him.', 'for', ['for', 'to', 'at'], 'buy → for.', EM('🎁')),
  Fl('I show ___ my photos.', 'her', ['her', 'she', 'hers'], 'Sau động từ dùng her.'),
  Fl('He gives a ticket ___ me.', 'to', ['to', 'for', 'at'], 'give → to.'),
  Fl('Mum makes a cake ___ us.', 'for', ['for', 'to', 'at'], 'make → for.'),
  Fl('She tells ___ a story.', 'us', ['us', 'we', 'our'], 'Sau động từ dùng us.', EM('📖')),
  Fl('Dad buys a ball ___ Tom.', 'for', ['for', 'to', 'at'], 'buy → for.'),
  Fl('I send ___ a message.', 'him', ['him', 'he', 'his'], 'Sau động từ dùng him.')],
 [Dlg(['Tom: Why is Amy happy?'], 'Ben: Her mum ___ her a new bag.', 'buys', 'buy', 'buying', 'Her mum → buys.'),
  Dlg(['Girl: Who gives you a ticket?'], 'Boy: My dad gives a ticket ___ me.', 'to', 'for', 'at', 'give → to.'),
  Dlg(['Teacher: Please show your picture.'], 'Pupil: I show ___ my picture.', 'you', 'I', 'your', 'Sau động từ dùng you.'),
  Clz(['It is Mum\'s birthday.', 'We want to make her happy.'], 'We buy a gift ___ her.', 'for', 'to', 'at', 'buy → for.', EM('🎁')),
  Clz(['Tom has two tickets.', 'Amy has none.'], 'Tom gives ___ a ticket.', 'her', 'she', 'hers', 'Sau động từ dùng her.', EM('🎟️')),
  Clz(['My friend lives far away.', 'I miss her.'], 'I send ___ a letter every week.', 'her', 'she', 'hers', 'Sau động từ dùng her.', EM('✉️'))])

